<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { api, apiMessage } from '@/api/client';
import type { Invitation } from '@/types';

const rows = ref<Invitation[]>([]); const error = ref(''); const message = ref(''); const busy = ref(false); const oneTimeLink = ref(''); const draft = reactive({ email: '', expiresInHours: 168 });
async function load() { rows.value = (await api.get<Invitation[]>('/admin/invitations')).data; }
function status(row: Invitation) { return row.revokedAt ? '已撤销' : row.acceptedAt ? '已接受' : new Date(row.expiresAt).getTime() <= Date.now() ? '已过期' : '有效'; }
async function create() { busy.value = true; error.value = ''; message.value = ''; oneTimeLink.value = ''; try { const { data } = await api.post<Invitation>('/admin/invitations', draft); draft.email = ''; oneTimeLink.value = data.registrationUrl ?? ''; message.value = data.registrationUrl ? '邮件服务不可用，注册链接仅在当前页面显示一次，请通过可信渠道发送给受邀人。' : '邀请邮件已发送。'; await load(); } catch (reason) { error.value = apiMessage(reason); } finally { busy.value = false; } }
async function revoke(row: Invitation) { if (!confirm(`撤销给 ${row.email} 的邀请？`)) return; busy.value = true; try { await api.delete(`/admin/invitations/${row.id}`); await load(); } catch (reason) { error.value = apiMessage(reason); } finally { busy.value = false; } }
async function copyLink() { try { await navigator.clipboard.writeText(oneTimeLink.value); message.value = '注册链接已复制。'; } catch { error.value = '浏览器无法访问剪贴板，请手动复制链接。'; } }
onMounted(() => load().catch(reason => error.value = apiMessage(reason)));
</script>
<template><div class="page"><header class="page-head"><div><p class="eyebrow">MEMBERS / INVITATIONS</p><h1>成员邀请</h1><p>管理员只能管理邀请生命周期；所有计划、主线与计时数据始终属于各自账号。</p></div></header><p v-if="error" class="error-text">{{ error }}</p><p v-if="message" class="success-text">{{ message }}</p><section class="members-layout"><form class="studio-section invite-form" @submit.prevent="create"><header class="section-title"><div><p class="eyebrow">NEW INVITATION</p><h2>创建邀请</h2></div></header><label>受邀邮箱<input v-model="draft.email" type="email" autocomplete="email" required /></label><label>有效小时数<input v-model.number="draft.expiresInHours" type="number" min="1" max="720" required /></label><button class="btn primary" :disabled="busy">{{ busy ? '正在创建…' : '创建邀请' }}</button><div v-if="oneTimeLink" class="one-time-link"><strong>一次性注册链接</strong><textarea :value="oneTimeLink" readonly rows="4"/><button class="btn" type="button" @click="copyLink">复制链接</button></div></form><section class="studio-section"><header class="section-title"><div><p class="eyebrow">INVITATION LEDGER</p><h2>邀请记录</h2></div><span>{{ rows.length }}</span></header><div class="table-scroll"><table><thead><tr><th>受邀邮箱</th><th>状态</th><th>到期时间</th><th>创建人</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.email }}</td><td>{{ status(row) }}</td><td>{{ new Date(row.expiresAt).toLocaleString('zh-CN') }}</td><td>{{ row.createdBy }}</td><td><button v-if="status(row)==='有效'" class="text-btn danger-text" :disabled="busy" @click="revoke(row)">撤销</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty">还没有邀请记录。</p></section></section></div></template>
